const express = require('express');
const cors = require('cors');
const app = express();

const allowedOrigins = ['https://myapp.com', 'https://admin.myapp.com'];

app.use(cors({
  origin: (origin, callback) => {
    // Allow requests with no origin (like mobile apps or curl)
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Blocked by CORS security policy!'));
    }
  },
  credentials: true
}));

import bcrypt from 'bcrypt';

const SALT_ROUNDS = 12; // Work factor cost

// 1. Hash password on signup
export async function hashPassword(plainTextPassword: string) {
  const hash = await bcrypt.hash(plainTextPassword, SALT_ROUNDS);
  return hash; // Store this hash in database!
}

// 2. Verify password on login
export async function verifyPassword(plainText: string, hashInDB: string) {
  const isMatch = await bcrypt.compare(plainText, hashInDB);
  return isMatch;
}

import jwt from 'jsonwebtoken';

export function verifyAccessToken(token: string) {
  return jwt.verify(token, process.env.JWT_SECRET!,
    // Explicitly restrict allowed algorithms to prevent alg confusion/none attacks!
    { algorithms: ['HS256'] }
  );
}

